#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals normedtype trigo. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Theorem triangle_value_c : forall (A B C : R * R) (a b c : R), A <> B -> B <> C -> C <> A -> let angle_ABC := angle (B.1 - A.1, B.2 - A.2) (C.1 - A.1, C.2 - A.2) in let angle_BCA := angle (C.1 - B.1, C.2 - B.2) (A.1 - B.1, A.2 - B.2) in let angle_CAB := angle (A.1 - C.1, A.2 - C.2) (B.1 - C.1, B.2 - C.2) in exists2 d : 'I_3, (angle_ABC == pi%:R / 3) || (angle_BCA == pi%:R / 2) || (angle_CAB == pi%:R / 6) & a = sqrt ((B.1 - C.1)^+2 + (B.2 - C.2)^+2) /\ b = sqrt ((C.1 - A.1)^+2 + (C.2 - A.2)^+2) /\ c = sqrt ((A.1 - B.1)^+2 + (A.2 - B.2)^+2). Proof. move=> AneqB BneqC CneqA. exists ord0; split; first by rewrite eq_refl. by [] Qed.
